"    // Calculate visible Y-range if not in manual scale mode (auto-zooming last 15 candles)
    if (!_isManualYScale && candleState.candles.isNotEmpty) {
      final list = candleState.candles;
      final int start = list.length > 15 ? list.length - 15 : 0;
      double minLow = double.infinity;
      double maxHigh = -double.infinity;
      for (int i = start; i < list.length; i++) {
        final c = list[i];
        double cLow = c.low;
        double cHigh = c.high;
        if (i == list.length - 1 && _animatedCloseNotifier.value != 0) {
          final liveClose = _animatedCloseNotifier.value;
          cLow = min(cLow, liveClose);
          cHigh = max(cHigh, liveClose);
        }
        if (cLow < minLow) minLow = cLow;
        if (cHigh > maxHigh) maxHigh = cHigh;
      }

      if (minLow != double.infinity && maxHigh != -double.infinity) {
        final range = maxHigh - minLow;
        final padding = range > 0 ? range * 0.08 : minLow * 0.01;
        _yVisibleMin = minLow - padding;
        _yVisibleMax = maxHigh + padding;
      }
    }"

